def comps2(G):
    H,W=len(G),len(G[0]); cnt={}
    for r in G:
        for x in r: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=lambda v:cnt[v])
    st=[(i,j) for i in range(H) for j in range(W) if G[i][j]!=bg]
    seen=set(); res=[]
    for p in sorted(st):
        if p in seen: continue
        stack=[p]; seen.add(p); cset={p}; col=G[p[0]][p[1]]
        while stack:
            y,x=stack.pop()
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    n_=(y+dy,x+dx)
                    if 0<=n_[0]<H and 0<=n_[1]<W and G[n_[0]][n_[1]]==col and n_ not in seen:
                        seen.add(n_); cset.add(n_); stack.append(n_)
        res.append((col,cset))
    return bg,res

