def place_objects(I):
    H,W=len(I),len(I[0])
    bg,ci_=comps2(I)
    _,co=comps2(I)
    anchors=[i for i,(c,cl) in enumerate(co) if min(x for y,x in cl)==0]
    a=min(anchors,key=lambda i:min(y for y,x in co[i][1]))
    cluster={(y,x) for y,x in co[a][1]}
    objs=[(c,cl) for i,(c,cl) in enumerate(co) if i!=a]
    placed=[[bg]*W for _ in range(H)]
    for c,cl in sorted(objs,key=lambda t:t[0]):
        found=None
        for ty in range(-4*H,H+1):
            for tx in range(-4*W,W+1):
                cc=[(y+ty,x+tx) for y,x in cl]
                if any(not(0<=y<H and 0<=x<W) for y,x in cc): continue
                if any((y,x) in cluster for y,x in cc): continue
                touch=any(abs(y-y2)<=1 and abs(x-x2)<=1 for y,x in cc for y2,x2 in cluster)
                key=(abs(touch)+1-abs(touch), sum(y for y,x in cc)/len(cc), -sum(x for y,x in cc)/len(cc))
                if found is None or key<found[0]: found=(key,cc)
        if found:
            for y,x in found[1]: cluster.add((y,x)); placed[y][x]=c
        else:
            print('FAIL',c,len(cl))
    return placed
