def solve_pack(I):
    H,W=len(I),len(I[0])
    bg,ci_=comps2(I)
    # absorb singles into nearest multi-comp (8-adj? use min cell distance)
    multis=[(c,cl) for c,cl in ci_ if len(cl)>1]
    objs=[]
    for c,cl in ci_:
        if len(cl)>1: objs.append((c,set(cl)))
        else:
            best=min(multis,key=lambda m:min(abs(y-y2)+abs(x-x2) for y,x in cl for y2,x2 in m[1]))
            objs.append((best[0],set(best[1])|{tuple(p) for p in cl}))
    anch=[i for i,(c,cl) in enumerate(objs) if min(x for y,x in cl)==0]
    a=anch[0]
    cluster={(y,x) for y,x in objs[a][1]}
    out=[[bg]*W for _ in range(H)]
    for y,x in objs[a][1]: out[y][x]=objs[a][0]
    others=sorted([(c,list(cl)) for i,(c,cl) in enumerate(objs) if i!=a], key=lambda t:-len(t[1]))
    for c,cl in others:
        found=None
        for ty in range(-4*H,H+1):
            for tx in range(-4*W,W+1):
                cc=[(y+ty,x+tx) for y,x in cl]
                if any(not(0<=y<H and 0<=x<W) for y,x in cc): continue
                if any((y,x) in cluster for y,x in cc): continue
                touch=any(abs(y-y2)<=1 and abs(x-x2)<=1 for y,x in cc for y2,x2 in cluster)
                dist=ty*ty+tx*tx
                key=(touch, -dist)
                if found is None or key<found[0]: found=((key,cc))
        if found:
            for y,x in found[1]: cluster.add((y,x)); out[y][x]=c
    ys=[i for i in range(H) if any(out[i][j]!=bg for j in range(W))]
    xs=[j for j in range(W) if any(out[i][j]!=bg for i in range(H))]
    return [[out[i][j] for j in range(min(xs),max(xs)+1)] for i in range(min(ys),max(ys)+1)]
for n in range(4,9):
